// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
require('dotenv').config(); // Para carregar variáveis de ambiente (chaves API)

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Conexão com o MongoDB (Substitua pela sua string de conexão)
mongoose.connect(process.env.MONGO_URI)
    .then(() => console.log('✅ Conectado ao MongoDB'))
    .catch(err => console.error('❌ Erro na conexão com DB:', err));

// Middleware para receber dados JSON
app.use(express.json());

// 🔗 CONFIGURAÇÃO DO SOCKET.IO
io.on('connection', (socket) => {
    console.log('🔌 Novo cliente conectado ao telão');

    // Quando um cliente (o telão) se conecta, envie os dados iniciais (Ranking e últimas 3 mensagens)
    // Aqui você chamaria o DB para buscar os dados
    socket.emit('update_dashboard', { 
        ranking: [], 
        mensagens: [] 
    });

    socket.on('disconnect', () => {
        console.log('🔌 Cliente desconectado');
    });
});

// ➡️ ROTA 1: Recebimento da Mensagem/PIX (Chamado pelo Frontend)
app.post('/api/submit-message', async (req, res) => {
    const { nome, mensagem, id_pix } = req.body;

    // 1. Salva no Banco de Dados
    // 2. Verifica o status do PIX (apenas se id_pix for enviado)

    // 3. Dispara a notificação em TEMPO REAL para o telão
    io.emit('new_submission', { nome, mensagem, status: 'Pendente' });

    res.status(200).send({ success: true, message: 'Mensagem recebida!' });
});


// ➡️ ROTA 2: WEBHOOK DO MERCADO PAGO (A mais importante)
app.post('/webhook/mercadopago', async (req, res) => {
    const event = req.body;
    // 🚨 Aqui você deve validar a assinatura do webhook para garantir que é o MP!

    if (event.type === 'payment' && event.data.status === 'approved') {
        const pago = event.data;
